# Harrington Exchange v3: real encoder + decoder, serialized container, exact round-trip check, ablation modes.
# Container: magic 'HE3' | J(1) S(1) mode(1) layout(1) K(2) nbytes(8) | len1(4) len2(4) | K source values (K*J bits, packed) | tail bits | zstd(stream1) | zstd(stream2)
# Targets are regenerated by the decoder from (J,S,K); only the K source values are stored.
import numpy as np, struct, itertools, subprocess, os
S_='/tmp/claude-0/-home-claude/8920de7d-b851-5d17-a34c-ae2e2bff24d6/scratchpad'; Z=S_+'/z3/zstd/programs/zstd'
def zc(b,l): return subprocess.run([Z,'-q',f'-{l}','-c'],input=b,capture_output=True,check=True).stdout
def zd(b): return subprocess.run([Z,'-q','-dc'],input=b,capture_output=True,check=True).stdout
def targets(J,S,K):
    out=[]
    for oh in range(0,S+1):
        for hi in itertools.combinations(range(S),oh):
            for ol in range(0,J-S+1):
                for lo in itertools.combinations(range(J-S),ol):
                    v=0
                    for b in hi: v|=1<<(J-1-b)
                    for b in lo: v|=1<<(J-S-1-b)
                    out.append(v)
                    if len(out)>=K: return out
    return out
def to_vals(data,J):
    bits=np.unpackbits(np.frombuffer(data,np.uint8)); n=len(bits)//J
    m=bits[:n*J].reshape(n,J); w=(np.uint64(1)<<np.arange(J-1,-1,-1,dtype=np.uint64))
    return (m.astype(np.uint64)*w).sum(1,dtype=np.uint64), bits[n*J:]
def to_bits(v,J): return ((v[:,None]>>np.arange(J-1,-1,-1,dtype=np.uint64))&np.uint64(1)).astype(np.uint8)
def perm(src,tg):
    s=set(src); t=set(tg); a=sorted(t-s); b=sorted(s-t)
    mp=dict(zip(src,tg)); mp.update(zip(a,b)); return mp
def apply(vals,mp):
    if not mp: return vals
    k=np.array(sorted(mp),np.uint64); v=np.array([mp[x] for x in sorted(mp)],np.uint64)
    pos=np.searchsorted(k,vals); pc=np.minimum(pos,len(k)-1); hit=k[pc]==vals
    out=vals.copy(); out[hit]=v[pc[hit]]; return out
def layout_pack(part,lay):
    if part.shape[1]==0: return b''
    if lay==0: return np.packbits(part.ravel()).tobytes()
    p=part.shape[1]; nb=(p+7)//8
    return np.packbits(np.hstack([np.zeros((part.shape[0],nb*8-p),np.uint8),part]),axis=1).tobytes()
def layout_unpack(buf,n,p,lay):
    if p==0: return np.zeros((n,0),np.uint8)
    a=np.unpackbits(np.frombuffer(buf,np.uint8))
    if lay==0: return a[:n*p].reshape(n,p)
    nb=(p+7)//8; return a.reshape(n,nb*8)[:,nb*8-p:]
# modes: full = rename+split+reverse; split = split+reverse (no rename); rename = rename only (one stream); norev = rename+split (no reverse)
def encode(data,J,S,K=256,mode='full',lay=0,level=19):
    vals,tail=to_vals(data,J); n=len(vals)
    if mode in ('full','rename','norev'):
        u,c=np.unique(vals,return_counts=True); src=[int(x) for x in u[np.argsort(-c,kind='stable')][:K]]
        tg=targets(J,S if mode!='rename' else max(1,J//2),len(src)); mp=perm(src,tg); vals2=apply(vals,mp)
    else: src=[]; vals2=vals
    b=to_bits(vals2,J)
    if mode=='rename': s1=layout_pack(b,lay); s2=b''
    else:
        hi=b[:,:S]; lo=b[:,S:]
        if mode!='norev': lo=lo[::-1]
        s1=layout_pack(hi,lay); s2=layout_pack(lo,lay)
    c1=zc(s1,level); c2=zc(s2,level) if s2 else b''
    hdr=b'HE3'+struct.pack('<BBBBHQII',J,S,['full','split','rename','norev'].index(mode),lay,len(src),len(data),len(c1),len(c2))
    srcb=np.packbits(to_bits(np.array(src,np.uint64),J).ravel()).tobytes() if src else b''
    tl=np.packbits(np.r_[tail,np.zeros((-len(tail))%8,np.uint8)]).tobytes()
    return hdr+srcb+tl+c1+c2
def decode(blob):
    J,S,mi,lay,K,nb,l1,l2=struct.unpack('<BBBBHQII',blob[3:25]); mode=['full','split','rename','norev'][mi]; p=25
    sl=(K*J+7)//8; src=[int(x) for x in (to_vals(blob[p:p+sl],J)[0][:K] if K else [])]; p+=sl
    nbits=nb*8; n=nbits//J; tb=nbits-n*J; tl=(tb+7)//8; tail=np.unpackbits(np.frombuffer(blob[p:p+tl],np.uint8))[:tb]; p+=tl
    s1=zd(blob[p:p+l1]); p+=l1; s2=zd(blob[p:p+l2]) if l2 else b''
    if mode=='rename': b=layout_unpack(s1,n,J,lay)
    else:
        hi=layout_unpack(s1,n,S,lay); lo=layout_unpack(s2,n,J-S,lay)
        if mode!='norev': lo=lo[::-1]
        b=np.hstack([hi,lo])
    w=(np.uint64(1)<<np.arange(J-1,-1,-1,dtype=np.uint64)); vals=(b.astype(np.uint64)*w).sum(1,dtype=np.uint64)
    if K:
        tg=targets(J,S if mode!='rename' else max(1,J//2),K); mp=perm(src,tg); inv={v:k for k,v in mp.items()}; vals=apply(vals,inv)
    bits=np.r_[to_bits(vals,J).ravel(),tail]
    return np.packbits(bits).tobytes()[:nb]
